import os, re, json, glob

root = '/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_9'
files = sorted(glob.glob(root + '/**/*', recursive=True))
files = [f for f in files if os.path.isfile(f)]

def norm(text):
    return re.sub(r'\s+', ' ', text).strip()

rows = []
for f in files:
    base = os.path.basename(f)
    num = base.split('_')[0]
    ext = base.rsplit('.',1)[-1].lower()
    if ext == 'pdf' or ext == 'xlsx':
        continue
    try:
        txt = open(f, encoding='utf-8', errors='replace').read()
    except Exception as e:
        continue

    # portfolio key
    pk = None
    m = re.search(r'CBP-001-(0[0-9]|1[0-2])', txt)
    if m: pk = 'CBP-001-' + m.group(1)

    # immutable entity (control field preferred)
    ent = None
    m = re.search(r'Immutable entity[^\n]*?ENT-001-(\d{4})', txt)
    if m: ent = 'ENT-001-' + m.group(1)
    else:
        m = re.search(r'immutable_entity["\']?\s*[:=]\s*["\']?(ENT-001-\d{4})', txt)
        if m: ent = m.group(1)

    # evidence role
    role = None
    m = re.search(r'Evidence role[^\n]*?\|\s*([a-z_]+)', txt)
    if m: role = m.group(1)
    else:
        m = re.search(r'evidence_role["\']?\s*[:=]\s*["\']?([a-z_]+)', txt)
        if m: role = m.group(1)

    # topic
    topic = None
    m = re.search(r'This record concerns\s+([a-z-]+)\s+within', txt)
    if m: topic = m.group(1)
    else:
        m = re.search(r'support row \d+ for\s+([a-z -]+);', txt)
        if m: topic = m.group(1)

    # operative body (native record) - json body field
    body = None
    if ext == 'json':
        try:
            j = json.loads(txt)
            body = j.get('body')
        except Exception:
            pass
    # md: blockquote after "## Native record"
    if not body:
        m = re.search(r'## Native record\s*\n\n(.*?)\n\n## ', txt, re.S)
        if m: body = norm(m.group(1))
    # txt: between "Native record" heading and next
    if not body:
        m = re.search(r'Native record\s*\n+(.*?)\n+\s*(Reliance|##|Source lineage)', txt, re.S)
        if m: body = norm(m.group(1))

    rows.append((num, ext, pk, ent, role, topic, body))

# Print compact map
for r in rows:
    num, ext, pk, ent, role, topic, body = r
    print(f"{num}.{ext} | {pk} | {ent} | {role} | {topic} | {body}")
