import os, re, json, glob, csv as csvmod, io

root = '/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_9'
files = sorted(glob.glob(root + '/**/*', recursive=True))
files = [f for f in files if os.path.isfile(f)]

def norm(t): return re.sub(r'\s+',' ',t).strip()

def get_body(txt, ext):
    # try common: NATIVE RECORD / native-record / body field / blockquote
    b = None
    if ext == 'json':
        try:
            j = json.loads(txt); b = j.get('body')
        except: pass
    if b: return norm(b)
    if ext == 'xml':
        m = re.search(r'<native-record>(.*?)</native-record>', txt, re.S)
        if m: return norm(m.group(1))
        m = re.search(r'<section heading="Native record">(.*?)</section>', txt, re.S)
        if m: return norm(m.group(1))
    if ext == 'html':
        m = re.search(r'<h2>Native record</h2><p>(.*?)</p>', txt, re.S)
        if m: return norm(m.group(1))
        m = re.search(r'</dl><p>(.*?)</p>', txt, re.S)
        if m: return norm(m.group(1))
    if ext == 'csv':
        # body is in metadata row value with "body"
        for line in txt.splitlines():
            if '"body"' in line or ',body,' in line:
                m = re.search(r',body,(.*?),[^,]+,[^,]+,[^,]+$', line)
                if m: return norm(m.group(1).strip('"'))
    if ext == 'eml':
        # first content paragraph after headers
        m = re.search(r'Content-Type: text/plain; charset=utf-8\n\n(.*?)\n\nSOURCE LINEAGE', txt, re.S)
        if m: return norm(m.group(1))
        m = re.search(r'\n\n(Crosswalk revision .*?)\n', txt)
        if m: return norm(m.group(1))
    if ext == 'txt':
        m = re.search(r'NATIVE RECORD\n(.*?)\n\nSOURCE LINEAGE', txt, re.S)
        if m: return norm(m.group(1))
    if ext == 'md':
        m = re.search(r'## Native record\n\n(.*?)\n\n## ', txt, re.S)
        if m: return norm(m.group(1))
        m = re.search(r'> (.*?)\n\n## ', txt, re.S)
        if m: return norm(m.group(1))
    return None

def get_pdf_text(path):
    try:
        from pypdf import PdfReader
        r = PdfReader(path)
        return "\n".join(p.extract_text() or '' for p in r.pages)
    except Exception as e:
        try:
            from PyPDF2 import PdfReader
            r = PdfReader(path)
            return "\n".join(p.extract_text() or '' for p in r.pages)
        except Exception as e2:
            return None

records = {}
for f in files:
    base = os.path.basename(f)
    num = base.split('_')[0]
    ext = base.rsplit('.',1)[-1].lower()
    if ext == 'xlsx': continue
    txt = None
    if ext == 'pdf':
        txt = get_pdf_text(f)
    else:
        try: txt = open(f, encoding='utf-8', errors='replace').read()
        except: continue
    if txt is None: continue
    pk = None
    m = re.search(r'CBP-001-(0[0-9]|1[0-2])', txt)
    if m: pk = 'CBP-001-'+m.group(1)
    role = None
    m = re.search(r'[Ee]vidence[- ]role[^A-Za-z]*?([a-z_]+)', txt)
    if m: role = m.group(1)
    body = get_body(txt, ext)
    # revision ref/current
    ref = None; cur = None
    m = re.search(r'[Rr]eferenced[- ]revision[^R]*?(REV-\d{4}\.\d+)', txt)
    if m: ref = m.group(1)
    m = re.search(r'[Cc]urrent[- ]revision[^R]*?(REV-\d{4}\.\d+)', txt)
    if m: cur = m.group(1)
    # entity key
    ent = None
    m = re.search(r'(?:[Ii]mmutable[- ]entity[- ]key|ENTITY KEY|Entity)[^\n]*?(ENT-001-\d{4})', txt)
    if m: ent = m.group(1)
    records[num] = dict(num=num, ext=ext, pk=pk, role=role, body=body, ref=ref, cur=cur, ent=ent)

# Print by key
from collections import defaultdict
bykey = defaultdict(dict)
for num, r in sorted(records.items(), key=lambda x:int(x[0])):
    if r['pk'] and r['role']:
        bykey[r['pk']][r['role']] = r
    print(f"{num}.{r['ext']} | {r['pk']} | {r['role']} | ref={r['ref']} cur={r['cur']} | ent={r['ent']}")
    if r['body']:
        print(f"      BODY: {r['body'][:220]}")
"}
